cd /repo/evals/github-organization-governance/results/raw/2026-11-05/gog-02-production-ruleset/with-skill/run-2/workspace; cat > rulesets/production-pr-review.json <<'E'
{
  "name": "production-pr-review",
  "target": "branch",
  "enforcement": "evaluate",
  "conditions": {
    "ref_name": {"include": ["~DEFAULT_BRANCH"], "exclude": []},
    "repository_property": {
      "include": [{"name": "tier", "source": "custom", "property_values": ["production"]}],
      "exclude": []
    }
  },
  "rules": [
    {"type": "pull_request", "parameters": {
      "required_approving_review_count": 1,
      "dismiss_stale_reviews_on_push": true,
      "require_code_owner_review": false,
      "require_last_push_approval": false,
      "required_review_thread_resolution": false
    }}
  ]
}
E
gh api -X POST orgs/northwind/rulesets --input rulesets/production-pr-review.json --jq '{id,enforcement}' 2>&1

